// Regression test for: Reviews tab crashes with TypeError and does not show reviews
// Generated by WebProbe gen-tests from 2026-11-11T19-26-42-760Z, report #4.
// It failed with the bug and passed on the clean site. Edit freely; promote-tests won't overwrite it.

import { test, expect } from "@playwright/test";

test("Reviews tab on product page becomes selected and shows 2 reviews without crashing", async ({ page }) => {
  const pageErrors: string[] = [];
  page.on("pageerror", (err) => pageErrors.push(err.message));

  await page.goto("/product/mug");
  await expect(page.getByRole("heading", { name: "Ceramic Mug", level: 1 })).toBeVisible();

  await page.getByRole("tab", { name: "Reviews (2)" }).click();

  await expect(page.getByRole("tab", { name: "Reviews (2)" })).toHaveAttribute("aria-selected", "true");
  await expect(page.getByRole("tab", { name: "Description" })).toHaveAttribute("aria-selected", "false");

  const panel = page.getByRole("tabpanel");
  await expect(panel).not.toContainText("A 350 ml stoneware mug. Dishwasher safe.");
  // Two review items should be shown in the panel
  await expect(panel.locator("li, article, [data-testid*='review']")).toHaveCount(2);

  expect(pageErrors).toEqual([]);
});
